const input = $input.first()?.json || {};
const rawMsg = input.sanitized_message || input.customer_message || 'Hello';

// Enterprise Guardrails: Detect Prompt Injection and Harmful Input
const injectionPatterns = [
  /ignore\s+(all\s+)?(previous|prior|above)\s+instructions/i,
  /system\s*prompt/i,
  /jailbreak/i,
  /bypass\s+rules/i,
  /disregard\s+guidelines/i,
  /تجاهل\s+(كافة|جميع)?\s+التعليمات/i,
  /تخطي\s+الحماية/i
];

let promptInjection = false;
for (const pattern of injectionPatterns) {
  if (pattern.test(rawMsg)) {
    promptInjection = true;
    break;
  }
}

return [{
  json: {
    ...input,
    guardrail_safe: !promptInjection,
    flagged_reason: promptInjection ? 'prompt_injection_attempt' : null
  }
}];

const item = $input.first()?.json || {};
const customerMsg = item.sanitized_message || item.customer_message || 'مرحبا';
const locale = item.locale || (customerMsg.match(/[\u0600-\u06FF]/) ? 'ar' : 'en');

if (!item.guardrail_safe) {
  const deflection = locale === 'ar'
    ? 'عذراً، لا يمكن معالجة هذا الطلب وفقاً لمعايير الأمان المعتمدة. كيف يمكنني مساعدتك في خدماتنا الرسمية؟'
    : 'Sorry, this request cannot be processed according to enterprise security policies. How may I assist you with our official services?';

  return [{
    json: {
      direct_bypass: true,
      ai_output: {
        intent: 'general_support',
        confidence: 0.99,
        entities: {},
        sentiment: 'neutral',
        requires_human: false,
        direct_response: deflection
      },
      ...item
    }
  }];
}

// Build Contextual Prompt for Ollama
const history = (item.conversation_history || []).slice(-3).map(h => `${h.sender_type}: ${h.content}`).join('\n');

const promptText = `You are the official Enterprise AI Cognitive Engine for the Ministry of Communications and Information Technology (MCIT) Customer Service Platform.
Analyze the incoming message (which may be Arabic or English) and classify it.

Rules:
1. If citizen/customer asks about order status, delivery, shipment, service request, tracking, or mentions a reference code (e.g. ORD-1001, SRV-1001), classify intent as 'order_lookup' and extract order_number entity.
2. If citizen asks about regulations, training programs (Future Skills), digital signatures, telecommunication complaints, working hours, or FAQs, classify intent as 'faq_query'.
3. If citizen is angry, frustrated, uses harsh language, demands a supervisor or human specialist, classify intent as 'human_escalation' and set requires_human to true.
4. Otherwise classify intent as 'general_support'.

Respond STRICTLY with a valid JSON object matching this schema:
{
  "intent": "order_lookup" | "faq_query" | "human_escalation" | "general_support",
  "confidence": 0.95,
  "entities": { "order_number": "..." },
  "sentiment": "positive" | "neutral" | "frustrated" | "angry",
  "requires_human": false,
  "direct_response": "polite contextual response in ${locale === 'ar' ? 'Arabic' : 'English'}"
}

${history ? 'Previous Context:\n' + history + '\n' : ''}
Customer Message: ${JSON.stringify(customerMsg)}`;

return [{
  json: {
    ollama_body: {
      model: 'llama3.1:8b',
      prompt: promptText,
      stream: false,
      format: 'json',
      options: {
        num_ctx: 1024,
        num_predict: 180,
        temperature: 0.2
      }
    },
    direct_bypass: false,
    customer_message: customerMsg,
    customer: item.customer,
    conversation: item.conversation,
    channel: item.channel,
    channel_user_id: item.channel_user_id,
    locale: locale
  }
}];

const nodeInput = $input.first()?.json || {};
const buildData = $('Build Prompt Payload').first()?.json || {};

if (buildData.direct_bypass) {
  return [{
    json: {
      ai_output: buildData.ai_output,
      customer_message: buildData.customer_message,
      customer: buildData.customer,
      conversation: buildData.conversation,
      channel: buildData.channel,
      channel_user_id: buildData.channel_user_id,
      locale: buildData.locale
    }
  }];
}

const rawResponse = nodeInput.response;
const originalMsg = (buildData.customer_message || '').toLowerCase();
const locale = buildData.locale || 'ar';

let parsed = null;
try {
  if (rawResponse) {
    parsed = JSON.parse(rawResponse);
  }
} catch (e) {
  parsed = null;
}

// Enterprise Heuristic Fail-Safe (Bilingual Arabic & English)
if (!parsed || !parsed.intent) {
  const isAr = locale === 'ar';

  const isOrder = originalMsg.includes('order') || originalMsg.includes('srv-') || originalMsg.includes('ord-') || originalMsg.includes('طلب') || originalMsg.includes('شحن') || originalMsg.includes('تتبع');
  const isEscalation = originalMsg.includes('human') || originalMsg.includes('supervisor') || originalMsg.includes('angry') || originalMsg.includes('موظف') || originalMsg.includes('مشرف') || originalMsg.includes('شكوى') || originalMsg.includes('إنسان');
  const isFaq = originalMsg.includes('skill') || originalMsg.includes('policy') || originalMsg.includes('hours') || originalMsg.includes('مهارات') || originalMsg.includes('ساعات') || originalMsg.includes('شروط') || originalMsg.includes('تقديم');

  if (isEscalation) {
    parsed = {
      intent: 'human_escalation',
      confidence: 0.95,
      entities: {},
      sentiment: 'frustrated',
      requires_human: true,
      direct_response: isAr ? 'يتم الآن تحويلك إلى ممثل خدمة العملاء المختص...' : 'Connecting you with a human support specialist...'
    };
  } else if (isOrder) {
    const match = originalMsg.match(/(?:ord|srv)-\d+/i);
    parsed = {
      intent: 'order_lookup',
      confidence: 0.90,
      entities: { order_number: match ? match[0].toUpperCase() : 'SRV-1001' },
      sentiment: 'neutral',
      requires_human: false,
      direct_response: isAr ? 'جاري الاستعلام عن بيانات طلبك...' : 'Looking up your service request details...'
    };
  } else if (isFaq) {
    parsed = {
      intent: 'faq_query',
      confidence: 0.90,
      entities: {},
      sentiment: 'neutral',
      requires_human: false,
      direct_response: isAr ? 'جاري البحث في قاعدة المعرفة المعتمدة...' : 'Searching the official knowledge base...'
    };
  } else {
    parsed = {
      intent: 'general_support',
      confidence: 0.75,
      entities: {},
      sentiment: 'neutral',
      requires_human: false,
      direct_response: isAr ? 'أهلاً بك في منصة خدمة العملاء لوزارة الاتصالات وتقنية المعلومات. كيف يمكننا مساعدتك اليوم؟' : 'Welcome to the MCIT Customer Service platform. How may we assist you today?'
    };
  }
}

// Ensure entity normalization
if (!parsed.entities) { parsed.entities = {}; }
if (!parsed.entities.order_number) {
  const match = originalMsg.match(/(?:ord|srv)-\d+/i);
  if (match) { parsed.entities.order_number = match[0].toUpperCase(); }
}

return [{
  json: {
    ai_output: parsed,
    customer_message: buildData.customer_message,
    customer: buildData.customer,
    conversation: buildData.conversation,
    channel: buildData.channel,
    channel_user_id: buildData.channel_user_id,
    locale: locale
  }
}];
